        // library treats SPD/SPSD inputs elsewhere, e.g. CHO/CHOP).
        static void ValidateLQRDims(in floatMxN A, in floatMxN B, in floatMxN Q, in floatMxN R,
                                    string ctx, out int n, out int m)
        {
            if (!A.IsSquare)
                throw new ArgumentException(ctx + ": A must be square");
            n = A.M_Rows;

            if (B.M_Rows != n)
                throw new ArgumentException(ctx + ": B.M_Rows must equal A's dimension");
            m = B.N_Cols;

            if (!Q.IsSquare || Q.M_Rows != n)
                throw new ArgumentException(ctx + ": Q must be n x n");

            if (!R.IsSquare || R.M_Rows != m)
                throw new ArgumentException(ctx + ": R must be m x m");

            for (int i = 0; i < m; i++)
            {
                float rd = R[i, i];
                if (!math.isfinite(rd) || rd < (float)0)
                    throw new ArgumentException(ctx + ": R diagonal must be finite and non-negative");
