            unsafe
            {
                float* p = M.Data.Ptr;
                int len = M.Data.Length;
                for (int i = 0; i < len; i++) s += (double)p[i] * (double)p[i];
            }
            return math.sqrt(s);
        }

        static double FrobeniusNormDiff(in floatMxN A, in floatMxN B)
