        // S⁻ = Q + AᵀSA - AᵀSB(R+BᵀSB)⁻¹BᵀSA,  K = (R+BᵀSB)⁻¹BᵀSA. The m x m solve is CHOP
        // unconditionally (see file header). On a hard CHOP failure (Indefinite -- R+BᵀSB is not even
        // PSD, only reachable from a numerically broken S) Snext/K are left UNTOUCHED (caller must
        // check .Solved before reading them); on RankDeficient the minimum-norm K/S⁻ are still
        // produced, and the caller is responsible for surfacing rankDeficientControl.
        internal static RankInfo RiccatiStep(in floatMxN A, in floatMxN B, in floatMxN Q, in floatMxN R,
                                             in floatMxN S, ref floatMxN Snext, ref floatMxN K)
        {
            int n = A.M_Rows, m = B.N_Cols;

            var SB = new floatMxN(n, m, Allocator.Temp);
            Blas.dot(in S, in B, ref SB);                          // SB = S*B

            var Rbar = new floatMxN(m, m, Allocator.Temp);
            Blas.dot(in B, in SB, ref Rbar, transposeA: true);     // Rbar = BᵀSB
            for (int i = 0; i < m; i++)
                for (int j = 0; j < m; j++)
                    Rbar[i, j] += R[i, j];                         // Rbar = R + BᵀSB

            var BSA = new floatMxN(m, n, Allocator.Temp);
            Blas.dot(in SB, in A, ref BSA, transposeA: true);      // BSA = (SB)ᵀA = BᵀSA

            var L = new floatMxN(m, m, Allocator.Temp);
            var P = new Pivot(m, Allocator.Temp);
            RankInfo rinfo = CHOP.decomp(in Rbar, ref L, ref P);

            if (rinfo.Solved)
            {
                for (int i = 0; i < m; i++)
                    for (int j = 0; j < n; j++)
                        K[i, j] = BSA[i, j];
                CHOP.decompSolve(ref L, in P, rinfo.rank, ref K);  // K := Rbar⁻¹ BSA

                var SA = new floatMxN(n, n, Allocator.Temp);
                Blas.dot(in S, in A, ref SA);                      // SA = S*A
                var AtSA = new floatMxN(n, n, Allocator.Temp);
                Blas.dot(in A, in SA, ref AtSA, transposeA: true); // AtSA = AᵀSA
                var BSATK = new floatMxN(n, n, Allocator.Temp);
                Blas.dot(in BSA, in K, ref BSATK, transposeA: true); // BSATK = BSAᵀK = AᵀSB*K

                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++)
                        Snext[i, j] = Q[i, j] + AtSA[i, j] - BSATK[i, j];

                SA.Dispose(); AtSA.Dispose(); BSATK.Dispose();
            }

            SB.Dispose(); Rbar.Dispose(); BSA.Dispose(); L.Dispose(); P.Dispose();
            return rinfo;
        }

