        /// <summary>
        /// Infinite-horizon discrete LQR, cold solve: computes the stabilizing feedback gain K (m x n,
        /// caller-allocated) so u = -Kx minimizes Σ(xᵀQx + uᵀRu) for x_{k+1} = Ax_k + Bu_k, via the
        /// discrete algebraic Riccati equation solved by SDA (structure-preserving doubling, port of
        /// Chiang-Fan-Lin Algorithm 2.1; quadratic convergence, ~10-25 steps typically). Use the
        /// <c>ref floatLQRState</c> overload instead when K
        /// will be re-solved repeatedly for a slightly-changing A/B (e.g. per-frame re-linearization).
        /// </summary>
        /// <param name="A">Dynamics, n x n.</param>
        /// <param name="B">Control input, n x m.</param>
        /// <param name="Q">State cost, n x n (assumed symmetric PSD; not numerically validated).</param>
        /// <param name="R">Control cost, m x m (assumed symmetric PSD; not numerically validated --
        /// only its diagonal's finiteness/non-negativity is checked).</param>
        /// <param name="K">Output feedback gain, m x n (overwritten).</param>
        /// <param name="maxIterations">SDA doubling-step budget; &lt;=0 picks the library default (50).</param>
        public static LQRInfo lqr(in floatMxN A, in floatMxN B, in floatMxN Q, in floatMxN R,
                                  ref floatMxN K, int maxIterations = 0)
        {
            ValidateLQRDims(in A, in B, in Q, in R, "Control.lqr", out int n, out int m);
            if (K.M_Rows != m || K.N_Cols != n)
                throw new ArgumentException("Control.lqr: K must be m x n");

            var S = new floatMxN(n, n, Allocator.Temp);
            var info = SolveCold(in A, in B, in Q, in R, ref K, ref S, maxIterations);
            S.Dispose();
            return info;
        }

        /// <summary>
        /// Infinite-horizon discrete LQR, warm-started: same problem as the cold overload, but reuses
        /// <paramref name="state"/>'s carried Riccati solution S across calls -- the per-frame re-
        /// linearization use case (A/B change slightly every call). If <paramref name="state"/> is
        /// already <c>populated</c> (from a prior call on a matching-shape problem), a cheap plain
        /// Riccati recursion (not SDA) iterates from the carried S; a slightly-changed A/B typically
        /// converges in a handful of steps. Otherwise runs the same cold SDA solve as the plain
        /// overload. The terminal S is written back into <paramref name="state"/> (and
        /// <c>populated</c> set true) ONLY on a <see cref="LQRStatus.Converged"/> exit, so a non-
        /// converged call never corrupts a future warm seed.
        /// </summary>
        /// <param name="state">Must be constructed via <c>new floatLQRState(n, allocator)</c> before
        /// the first call (job-safe: this overload never allocates). Dimension mismatch against A/Q
        /// throws.</param>
        /// <param name="maxIterations">Iteration budget for whichever path runs (SDA if cold, the plain
        /// recursion if warm); &lt;=0 picks that path's own library default (50 cold / 500 warm).</param>
        public static LQRInfo lqr(in floatMxN A, in floatMxN B, in floatMxN Q, in floatMxN R,
                                  ref floatMxN K, ref floatLQRState state, int maxIterations = 0)
        {
            ValidateLQRDims(in A, in B, in Q, in R, "Control.lqr", out int n, out int m);
            if (K.M_Rows != m || K.N_Cols != n)
                throw new ArgumentException("Control.lqr: K must be m x n");

            if (!state.IsCreated)
                throw new ArgumentException("Control.lqr: state must be constructed via new floatLQRState(n, allocator) before use");
            if (!state.IsValid(n))
                throw new ArgumentException("Control.lqr: state dimensions do not match A");

            LQRInfo info;
            if (state.populated)
            {
                var Snew = new floatMxN(n, n, Allocator.Temp);
                info = RiccatiIterate(in A, in B, in Q, in R, in state.S, ref Snew, ref K, maxIterations);
                if (info.status == LQRStatus.Converged)
                    state.S.Data.CopyFrom(Snew.Data);
                Snew.Dispose();
            }
            else
            {
                var Scold = new floatMxN(n, n, Allocator.Temp);
                info = SolveCold(in A, in B, in Q, in R, ref K, ref Scold, maxIterations);
                if (info.status == LQRStatus.Converged)
                    state.S.Data.CopyFrom(Scold.Data);
                Scold.Dispose();
            }

            if (info.status == LQRStatus.Converged)
                state.populated = true;

            return info;
        }

        /// <summary>
        /// Finite-horizon discrete LQR: backward Riccati recursion from the terminal cost
        /// <paramref name="Qf"/> over <paramref name="N"/> steps, using the SAME shared Riccati-step
        /// kernel as the infinite-horizon paths. <paramref name="Kschedule"/> is (N*m) x n; the gain
        /// for step k lives in rows [k*m, (k+1)*m). For large N with <c>Qf == Q</c>, row block 0
        /// approaches the infinite-horizon K.
        /// </summary>
        /// <param name="N">Horizon length, &gt;= 1.</param>
        /// <param name="Kschedule">Output, (N*m) x n (overwritten row-block by row-block).</param>
        public static LQRInfo lqrSchedule(in floatMxN A, in floatMxN B, in floatMxN Q, in floatMxN R,
                                          in floatMxN Qf, int N, ref floatMxN Kschedule)
        {
            ValidateLQRDims(in A, in B, in Q, in R, "Control.lqrSchedule", out int n, out int m);
            if (!Qf.IsSquare || Qf.M_Rows != n)
                throw new ArgumentException("Control.lqrSchedule: Qf must be n x n");
            if (N < 1)
                throw new ArgumentException("Control.lqrSchedule: N must be >= 1");
            if (Kschedule.M_Rows != N * m || Kschedule.N_Cols != n)
                throw new ArgumentException("Control.lqrSchedule: Kschedule must be (N*m) x n");

            var Sk = new floatMxN(in Qf, Allocator.Temp);
            var Snext = new floatMxN(n, n, Allocator.Temp);
            var Kstep = new floatMxN(m, n, Allocator.Temp);

            double blowup = BlowupThreshold(in Q, in Qf);
            bool rankDeficient = false;
            LQRStatus status = LQRStatus.Converged;
            int steps = 0;
            double residual = double.PositiveInfinity;

            for (int k = N - 1; k >= 0; k--)
            {
                var rinfo = RiccatiStep(in A, in B, in Q, in R, in Sk, ref Snext, ref Kstep);
                steps++;
                if (!rinfo.Solved) { status = LQRStatus.Diverged; residual = double.PositiveInfinity; break; }
                if (rinfo.status == DirectSolveStatus.RankDeficient) rankDeficient = true;

                SymmetrizeInPlace(ref Snext);
                double newNorm = FrobeniusNorm(in Snext);
                if (!(newNorm <= blowup)) { status = LQRStatus.Diverged; residual = double.PositiveInfinity; break; }

                for (int r = 0; r < m; r++)
                    for (int c = 0; c < n; c++)
                        Kschedule[k * m + r, c] = Kstep[r, c];

                residual = FrobeniusNormDiff(in Snext, in Sk) / math.max(1.0, newNorm);

                Sk.Data.CopyFrom(Snext.Data);
            }

            Sk.Dispose(); Snext.Dispose(); Kstep.Dispose();

            return new LQRInfo { iterations = steps, residual = residual, status = status, rankDeficientControl = rankDeficient };
        }
    }

    /// <summary>
    /// Buffer-carrying warm-start state for <see cref="Control.lqr(in floatMxN, in floatMxN, in floatMxN, in floatMxN, ref floatMxN, ref floatLQRState, int)"/>:
    /// carries the n x n Riccati solution S across separate top-level calls, for LQR's per-frame
    /// re-linearization use case. Standalone, user-allocated (no arena requirement), since it must
    /// persist across separate solve calls. MUST be constructed via <c>(n, Allocator)</c> before being
    /// passed to the warm <c>lqr</c> overload -- an uncreated instance is a caller error and <c>lqr</c>
    /// throws rather than silently falling back to a cold solve.
    /// </summary>
    public struct floatLQRState
    {
        /// <summary>Carried Riccati solution, n x n. Meaningful only when <see cref="populated"/>.</summary>
        public floatMxN S;

        /// <summary>False on a freshly-constructed instance. <c>lqr(..., ref state)</c> sets this true
        /// (and writes the terminal S) ONLY on a <see cref="LQRStatus.Converged"/> exit -- a non-
        /// converged call never corrupts a future warm seed.</summary>
        public bool populated;

        /// <summary>Allocates a state sized for an n x n Riccati solution. <see cref="populated"/>
        /// starts false, so the first <c>lqr(..., ref state)</c> call using this instance always takes
        /// the cold SDA path.</summary>
        public floatLQRState(int n, Allocator allocator)
        {
            S = new floatMxN(n, n, allocator);
            populated = false;
        }

        /// <summary>True once <see cref="S"/> is allocated (regardless of <see cref="populated"/>).</summary>
        public bool IsCreated => S.Data.IsCreated;

        /// <summary>True iff created AND sized for exactly <paramref name="n"/>.</summary>
        public bool IsValid(int n) => IsCreated && S.M_Rows == n && S.N_Cols == n;

        /// <summary>Releases <see cref="S"/>. Safe to call on an empty/already-disposed instance.</summary>
        public void Dispose()
        {
            if (S.Data.IsCreated) S.Dispose();
        }
    }
}
